import Foundation

/// Frozen per interfaces.json, owning_lane primary_ui. Field shape (six public
/// stored properties) matches the contract verbatim so anything constructing
/// this type elsewhere stays compatible. Construction is routed through the
/// static factories below so the "loose booleans that can form impossible
/// combinations" failure mode the product rules warn about can't actually
/// happen — e.g. there's no way to build a value with both isEmpty and
/// hasError true, or isLoading true with a non-empty decks array.
public struct DeckListViewState: Equatable, Sendable {
    public let isLoading: Bool
    public let isEmpty: Bool
    public let allCaughtUp: Bool
    public let decks: [DeckCellVM]
    public let hasError: Bool
    public let errorMessage: String?

    private init(
        isLoading: Bool,
        isEmpty: Bool,
        allCaughtUp: Bool,
        decks: [DeckCellVM],
        hasError: Bool,
        errorMessage: String?
    ) {
        self.isLoading = isLoading
        self.isEmpty = isEmpty
        self.allCaughtUp = allCaughtUp
        self.decks = decks
        self.hasError = hasError
        self.errorMessage = errorMessage
    }

    public static let loading = DeckListViewState(
        isLoading: true, isEmpty: false, allCaughtUp: false, decks: [], hasError: false, errorMessage: nil
    )

    /// True empty: the user has never created a deck. Distinct from allCaughtUp
    /// per DEC-design_discussion-005 — different facts, different copy.
    public static let noDecksYet = DeckListViewState(
        isLoading: false, isEmpty: true, allCaughtUp: false, decks: [], hasError: false, errorMessage: nil
    )

    /// Decks exist, but nothing is due today. The deck list itself still renders
    /// (each deck showing 0 due) — this is a banner on top of real content, not
    /// a replacement full-screen state.
    public static func allCaughtUp(decks: [DeckCellVM]) -> DeckListViewState {
        DeckListViewState(isLoading: false, isEmpty: false, allCaughtUp: true, decks: decks, hasError: false, errorMessage: nil)
    }

    public static func populated(decks: [DeckCellVM]) -> DeckListViewState {
        DeckListViewState(isLoading: false, isEmpty: false, allCaughtUp: false, decks: decks, hasError: false, errorMessage: nil)
    }

    public static func failed(_ message: String) -> DeckListViewState {
        DeckListViewState(isLoading: false, isEmpty: false, allCaughtUp: false, decks: [], hasError: true, errorMessage: message)
    }
}

